(function () {
  const e = PL.esc, rs = PL.rs, S = PL.state; S.preset = 'today'; S.from = ''; S.to = '';
  const paise = (v) => Math.round(Number(v || 0) * 100);
  const A = (p) => PL.api('/api/admin' + p), P = (p, b) => PL.post('/api/admin' + p, b);
  const tbl = (head, rows) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c, i) => `<td data-label="${e(head[i])}" ${i === r.length - 1 && head[i] === '' ? 'class="act"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  const stat = (v, l, hint) => `<div class="stat"><div class="v">${v}</div><div class="l">${l}</div>${hint ? `<div class="small mute">${hint}</div>` : ''}</div>`;

  const shortDate = (d) => new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
  // dependency-free SVG chart that scales to any screen width
  // Values come straight from /api/admin/overview: "collected" = totals of orders DELIVERED that day, "revenue" = platform
  // ledger entries (markup, commission, delivery margin, surge) posted at delivery. Nothing is estimated or filled in here.
  const niceMax = (v) => { if (v <= 0) return 0; const p = 10 ** Math.floor(Math.log10(v)), f = v / p; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; };
  const rsShort = (p) => { const r = p / 100; return '₹' + (r >= 1e5 ? +(r / 1e5).toFixed(1) + 'L' : r >= 1e3 ? +(r / 1e3).toFixed(1) + 'k' : Math.round(r)); };
  const chart = (daily) => {
    const n = daily.length, pos = (v) => Math.max(0, Number(v) || 0);
    const totC = daily.reduce((s, d) => s + pos(d.collected_paise), 0), totR = daily.reduce((s, d) => s + pos(d.revenue_paise), 0), totO = daily.reduce((s, d) => s + (d.orders || 0), 0);
    const span = n ? (n === 1 ? shortDate(daily[0].date) : `${shortDate(daily[0].date)} – ${shortDate(daily[n - 1].date)}`) : '';
    if (!n || (!totC && !totR)) return `<div class="empty" style="padding:22px 10px"><b>No delivered orders in this range</b><div class="small mt2">${e(span)}. The chart fills in when orders are delivered; cancelled, rejected and unpaid orders are not counted.${S.preset === 'today' || S.preset === 'yesterday' ? ' Try “Last 7 days” or “Last 30 days”.' : ''}</div></div>`;
    const W = 360, H = 190, L = 44, R = 8, B = 24, T = 12, max = niceMax(Math.max(...daily.map((d) => Math.max(pos(d.collected_paise), pos(d.revenue_paise))))), slot = (W - L - R) / n, bw = Math.max(2, Math.min(22, slot * 0.36)), y = (v) => T + (H - B - T) * (1 - pos(v) / max);
    const grid = [0, 0.5, 1].map((f) => `<line x1="${L}" x2="${W - R}" y1="${y(max * f)}" y2="${y(max * f)}" stroke="#e8e6e1" ${f ? 'stroke-dasharray="3 3"' : ''}/><text x="${L - 6}" y="${y(max * f) + 3}" text-anchor="end" font-size="9" fill="#667069">${rsShort(max * f)}</text>`).join('');
    const bar = (x, v, fill, tip) => { const h = H - B - y(v); return `<rect x="${x}" y="${y(v) - (v > 0 && h < 2 ? 2 - h : 0)}" width="${bw}" height="${v > 0 ? Math.max(2, h) : 0}" rx="2" fill="${fill}"><title>${tip}</title></rect>`; };
    const bars = daily.map((d, i) => { const x = L + slot * i + slot / 2, day = shortDate(d.date), c = pos(d.collected_paise), r = pos(d.revenue_paise);
      return `<g>${bar(x - bw - 1, c, '#9fb3a8', `${day}: collected ${rs(c)} from ${d.orders || 0} delivered order${d.orders === 1 ? '' : 's'}`)}${bar(x + 1, r, '#d4500f', `${day}: platform revenue ${rs(r)}`)}</g>`; }).join('');
    const idx = n <= 8 ? daily.map((_, i) => i) : [0, Math.floor((n - 1) / 3), Math.floor((2 * (n - 1)) / 3), n - 1];
    const lab = (i) => `<text x="${L + slot * i + slot / 2}" y="${H - 7}" text-anchor="middle" font-size="9" fill="#667069">${shortDate(daily[i].date)}</text>`;
    return `<div class="row between wrap small"><span class="mute">${e(span)} · ${totO} delivered order${totO === 1 ? '' : 's'}</span><span><b>${rs(totC)}</b> <span class="mute">collected</span> · <b>${rs(totR)}</b> <span class="mute">platform revenue</span></span></div>
      <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily collected versus platform revenue, ${e(span)}" style="width:100%;max-width:720px;max-height:300px;height:auto;display:block;margin:6px auto 0">${grid}${bars}${idx.map(lab).join('')}</svg>
      <div class="row small mute wrap" style="gap:14px;margin-top:6px"><span><i style="display:inline-block;width:10px;height:10px;border-radius:2px;background:#9fb3a8"></i> Collected from customers</span><span><i style="display:inline-block;width:10px;height:10px;border-radius:2px;background:#d4500f"></i> Platform revenue</span>${n === 1 ? '<span>Single day. Choose “Last 7 days” to see a trend.</span>' : ''}</div>`; };
  // ---------- overview ----------
  async function overview() { const q = S.preset === 'custom' ? `?preset=custom&from=${S.from}&to=${S.to}` : `?preset=${S.preset}`; const [o, n] = await Promise.all([A('/overview' + q), A('/notifications')]); const m = o.money, c = o.current;
    return `<div class="tabs">${[['today', 'Today'], ['yesterday', 'Yesterday'], ['7d', 'Last 7 days'], ['30d', 'Last 30 days'], ['custom', 'Custom']].map(([k, l]) => `<button class="${S.preset === k ? 'on' : ''}" data-act="preset" data-k="${k}">${l}</button>`).join('')}</div>
      ${S.preset === 'custom' ? `<form data-form="range" class="row wrap" style="margin-bottom:12px"><input type="date" name="from" value="${S.from}" required style="width:auto"><input type="date" name="to" value="${S.to}" required style="width:auto"><button class="btn sm" type="submit">Apply</button></form>` : ''}
      ${o.riders_available ? '' : '<div class="banner warn">No delivery partners are online. Customers cannot place orders.</div>'}
      <div class="sec">Live orders</div><div class="stats">${stat(c.pending_acceptance, 'Awaiting restaurant')}${stat(c.preparing, 'Preparing')}${stat(c.ready, 'Ready for pickup')}${stat(c.active_deliveries, 'Out for delivery')}${stat(c.delivered, 'Delivered (range)')}${stat(c.rejected, 'Rejected (range)')}${stat(o.riders_available, 'Riders online')}${stat(o.pending_cashouts, 'Cashouts pending')}</div>
      <div class="sec">Revenue today vs yesterday</div><div class="stats">${stat(rs(m.today_revenue_paise), 'Platform revenue today')}${stat(rs(m.yesterday_revenue_paise), 'Yesterday')}${stat(rs(m.all_time_revenue_paise), 'All-time platform revenue')}</div>
      <div class="sec">Daily trend</div><div class="card">${chart(o.daily)}</div><div class="sec">Money in selected range</div><div class="stats">${stat(rs(m.collected_paise), 'Collected from customers', 'Not profit')}${stat(rs(m.platform_revenue_paise), 'Gross platform earnings')}${stat(rs(m.estimated_net_profit_paise), 'Estimated net profit', 'After gateway fees and expenses')}${stat(rs(m.expenses_paise), 'Operating expenses')}${stat(rs(m.commission_paise), 'Restaurant commission')}${stat(rs(m.markup_paise), 'Item markup')}${stat(rs(m.delivery_margin_paise), 'Delivery margin', 'Delivery charge − rider pay')}${stat(rs(m.surge_paise), 'Surge charges')}${stat(rs(m.delivery_collected_paise), 'Delivery charges collected')}${stat(rs(m.refunds_paise), 'Refunds')}${stat(rs(m.gateway_fee_estimate_paise), 'Est. gateway fees')}</div>
      <div class="sec">Liabilities (not our money)</div><div class="stats">${stat(rs(m.restaurant_payable_paise), 'Restaurant balances unpaid')}${stat(rs(m.rider_payable_paise), 'Rider balances unpaid')}${stat(rs(m.tax_liability_paise), 'Tax collected')}</div>
      <div class="sec">Alerts</div>${n.notifications.slice(0, 8).map((x) => `<div class="card"><b>${e(x.title)}</b><div class="small mute">${e(x.body)} · ${PL.dt(x.created_at)}</div></div>`).join('') || '<div class="empty">Nothing needs attention.</div>'}`; }
  PL.actions.preset = (el) => { S.preset = el.dataset.k; PL.rerender(); };
  PL.forms.range = (f) => { const v = PL.form(f); S.from = v.from; S.to = v.to; PL.rerender(); };

  // ---------- orders + search ----------
  async function orders() { const { orders } = await A('/orders' + (S.ofilter ? '?status=' + S.ofilter : ''));
    return `<select data-act-change="x" id="ofil"><option value="">All orders</option>${['PLACED', 'ACCEPTED', 'PREPARING', 'READY', 'PICKED_UP', 'DELIVERED', 'REJECTED', 'PAYMENT_FAILED', 'EXPIRED'].map((s) => `<option ${S.ofilter === s ? 'selected' : ''}>${s}</option>`).join('')}</select><div class="mt">${tbl(['Order', 'Restaurant', 'Customer', 'Total', 'Status', ''], orders.map((o) => [PL.code(o.order_code), e(o.restaurant), e(o.customer_name || ''), rs(o.total_paise), PL.chip(o.status), `<button class="btn ghost sm" data-act="go" data-path="/search/${o.order_code}">Open</button>`]))}</div>`; }
  document.addEventListener('change', (ev) => { if (ev.target.id === 'ofil') { S.ofilter = ev.target.value; PL.rerender(); } });
  async function search() { return `<h2>Order ID search</h2><form data-form="osearch" class="row mt2"><input name="code" placeholder="PL20261104A1B2C3" required style="text-transform:uppercase"><button class="btn" type="submit">Search</button></form><p class="small mute mt2">Finds any order across all restaurants.</p>`; }
  PL.forms.osearch = (f) => PL.go('/search/' + encodeURIComponent(PL.form(f).code.trim().toUpperCase()));
  async function orderDetail({ code }) { let d; try { d = await A('/orders/search/' + code); } catch (x) { return `<div class="banner bad">${e(x.message)}</div>`; } const o = d.order;
    return `<div class="card"><div class="row between">${PL.code(o.order_code)}${PL.chip(o.status)}</div><div class="small mute">${PL.dt(o.created_at)}</div>${o.rejection_reason ? `<div class="small mt2" style="color:var(--bad)">${e(o.rejection_reason)}</div>` : ''}
        ${['PLACED', 'ACCEPTED', 'PREPARING', 'READY', 'PICKED_UP'].includes(o.status) ? `<div class="row wrap mt2"><button class="btn danger sm" data-act="ocancel" data-id="${o.id}">Cancel order and refund</button>${o.rider_id && ['ACCEPTED', 'PREPARING', 'READY'].includes(o.status) ? `<button class="btn ghost sm" data-act="ounassign" data-id="${o.id}">Take rider off this order</button>` : ''}</div>` : ''}</div>
      <div class="grid g2"><div class="card"><h3>Customer</h3><p>${e(o.customer_name || '')}<br>${e(o.customer_phone || '')}</p><div class="small">${e(o.dest_text)}</div>${o.instructions ? `<div class="small mt2"><b>Instructions:</b> ${e(o.instructions)}</div>` : ''}${PL.mapsBtn(o.dest_maps_link, 'Map')}</div>
      <div class="card"><h3>Restaurant</h3><p>${e(d.restaurant.name)}<br>${e(d.restaurant.phone || '')}</p><h3 class="mt2">Delivery partner</h3><p>${d.rider ? `${e(d.rider.name)} · ${e(d.rider.phone)}<br>${e(d.rider.vehicle_reg_no || '')}` : '<span class="mute">Not assigned</span>'}</p></div></div>
      <div class="card"><h3>Items</h3>${tbl(['Item', 'Qty', 'Restaurant price', 'Customer price'], d.items.map((i) => [e(i.name), i.qty, rs(i.base_price_paise), rs(i.customer_price_paise)]))}</div>
      <div class="grid g2"><div class="card"><h3>Customer paid</h3><div class="kv"><span>Items (restaurant)</span><span>${rs(o.items_base_paise)}</span></div><div class="kv"><span>Markup</span><span>${rs(o.markup_paise)}</span></div><div class="kv"><span>Delivery</span><span>${rs(o.delivery_paise)}</span></div><div class="kv"><span>Surge</span><span>${rs(o.surge_paise)}</span></div><div class="kv"><span>Taxes</span><span>${rs(o.tax_paise)}</span></div><div class="kv tot"><span>Total</span><span>${rs(o.total_paise)}</span></div>
        <div class="small mt2">Payment: ${d.payment.provider} · ${PL.chip(d.payment.status)}<br>Ref: <span class="code">${e(d.payment.provider_txn_id || d.payment.merchant_order_id)}</span></div>${d.refund ? `<div class="mt2">Refund ${PL.chip(d.refund.status)} ${rs(d.refund.amount_paise)}<div class="small mute">${e(d.refund.reason || '')}</div>${d.refund.status === 'REFUND_INITIATED' ? `<div class="row mt2"><button class="btn sm" data-act="refund" data-id="${d.refund.id}" data-ok="1">Sandbox: mark refunded</button><button class="btn danger sm" data-act="refund" data-id="${d.refund.id}" data-ok="0">Mark failed</button></div>` : ''}</div>` : ''}</div>
      <div class="card"><h3>Who earns what</h3><div class="kv"><span>Restaurant commission (${o.commission_bps / 100}%)</span><span>${rs(o.commission_paise)}</span></div><div class="kv"><span>Restaurant payout</span><span>${rs(o.restaurant_payout_paise)}</span></div><div class="kv"><span>Rider earning</span><span>${rs(o.rider_payout_paise)}</span></div><div class="kv tot"><span>Platform revenue</span><span>${rs(d.platform_revenue_paise)}</span></div><div class="small mute">Markup + commission + delivery margin + surge</div></div></div>
      <div class="card"><h3>Activity</h3>${d.events.map((x) => `<div class="kv"><span><b>${e(x.event_type.replace(/_/g, ' ').toLowerCase())}</b><div class="small mute">${e(x.actor_name || x.actor_role || 'system')}</div></span><span class="small mute">${PL.dt(x.created_at)}</span></div>`).join('')}</div>`; }
  PL.actions.ocancel = (el) => PL.modal(`<h3>Cancel this order?</h3><p class="small mute">The customer is refunded (tracked until the payment provider confirms), and the restaurant and rider are told. This can’t be undone.</p><form data-form="ocancel" data-id="${el.dataset.id}"><label>Reason (recorded in the order history)</label><input name="reason" required minlength="3" maxlength="300"><button class="btn danger block mt" type="submit">Cancel order</button></form>`);
  PL.forms.ocancel = async (f) => { const reason = PL.form(f).reason, id = f.dataset.id; PL.closeModal();
    const r = await PL.reauth('Confirm cancellation', (a) => P(`/orders/${id}/cancel`, { reason, ...a })); if (r) { PL.toast('Order cancelled'); setTimeout(PL.rerender, 100); } };
  PL.actions.ounassign = (el) => PL.modal(`<h3>Take the rider off this order?</h3><p class="small mute">Other riders will be offered it. The rider is notified.</p><form data-form="ounassign" data-id="${el.dataset.id}"><label>Reason (required, kept in the audit log)</label><textarea name="note" minlength="3" maxlength="300" required></textarea><button class="btn danger block mt" type="submit">Continue</button></form>`);
  PL.forms.ounassign = async (f) => { const note = PL.form(f).note, id = f.dataset.id; PL.closeModal();
    const r = await PL.reauth('Confirm taking the rider off', (a) => P(`/orders/${id}/unassign-rider`, { note, ...a })); if (r) { PL.toast('Rider removed; order re-offered'); PL.rerender(); } };
  PL.actions.refund = async (el) => { const r = await PL.run(() => P(`/refunds/${el.dataset.id}/settle`, { ok: el.dataset.ok === '1' }), 'Refund updated'); if (r) PL.rerender(); };

  // ---------- restaurants ----------
  async function restaurants() { const { restaurants: rs_ } = await A('/restaurants');
    return `<div class="row between"><h2>Restaurants</h2><button class="btn sm" data-act="rest-edit">${PL.icon('plus', 'width="18" height="18"')} Add</button></div><div class="mt2">${rs_.map((r) => `<div class="card"><div class="row between"><h3>${e(r.name)}</h3><button class="sw ${r.admin_visible ? 'on' : ''}" data-act="rest-vis" data-id="${r.id}" data-v="${r.admin_visible ? 0 : 1}" aria-label="Show or hide"><span>${r.admin_visible ? 'Visible' : 'Hidden'}</span><i></i></button></div>
      <div class="small mute">${e(r.address || '')} · owner ${e(r.owner_phone || 'no login yet')} · ${r.is_open ? 'Open' : 'Closed'} ${r.approved ? '' : '· <b>Not approved</b>'}</div><div class="stats mt2">${stat(r.commission_bps / 100 + '%', 'Commission')}${stat(rs(r.markup_paise), 'Markup / item')}${stat(rs(r.balance.available), 'Payout balance')}${stat(rs(r.balance.earned), 'Total earned')}</div>
      <div class="row wrap mt2"><button class="btn ghost sm" data-act="rest-edit" data-id="${r.id}">Edit</button><button class="btn ghost sm" data-act="rest-owner" data-id="${r.id}">${r.owner_phone ? 'Add another login' : 'Create owner login'}</button><button class="btn ghost sm" data-act="rest-menu" data-id="${r.id}">View menu</button><button class="btn ghost sm" data-act="rest-orders" data-id="${r.id}">Orders</button><button class="btn ghost sm" data-act="rest-users" data-id="${r.id}">Logins</button></div><div class="small mute mt2">${r.min_order_paise ? 'Min order ' + rs(r.min_order_paise) : 'No minimum order'} · ${r.free_delivery_above_paise ? 'Free delivery above ' + rs(r.free_delivery_above_paise) : 'No free-delivery rule'}</div></div>`).join('') || '<div class="empty">No restaurants yet.</div>'}</div>`; }
  PL.actions['rest-vis'] = async (el) => { const r = (await A('/restaurants')).restaurants.find((x) => x.id == el.dataset.id); const res = await PL.run(() => PL.put('/api/admin/restaurants/' + r.id, { name: r.name, admin_visible: el.dataset.v === '1' }), el.dataset.v === '1' ? 'Restaurant is now visible' : 'Restaurant hidden from customers'); if (res) PL.rerender(); };
  PL.actions['rest-edit'] = async (el) => { const r = el.dataset.id ? (await A('/restaurants')).restaurants.find((x) => x.id == el.dataset.id) : { commission_bps: 1000, markup_paise: 0, packing_buffer_min: 5, approved: 1, admin_visible: 1 };
    PL.modal(`<h3>${r.id ? 'Edit' : 'Add'} restaurant</h3><form data-form="rest" data-id="${r.id || ''}"><label>Name</label><input name="name" value="${e(r.name || '')}" required><label>Cuisine</label><input name="cuisine" value="${e(r.cuisine || '')}"><label>Address</label><input name="address" value="${e(r.address || '')}"><label>Phone</label><input name="phone" value="${e(r.phone || '')}">
      <div class="grid g2"><div><label>Commission (%)</label><input name="commission" inputmode="decimal" value="${r.commission_bps / 100}" required></div><div><label>Markup per item (₹)</label><input name="markup" inputmode="decimal" value="${r.markup_paise / 100}" required></div></div><label>Packing buffer (min)</label><input name="buffer" type="number" min="0" max="60" value="${r.packing_buffer_min}"><div class="grid g2"><div><label>Minimum order (₹)</label><input name="minorder" inputmode="decimal" value="${(r.min_order_paise || 0) / 100}"></div><div><label>Free delivery above (₹)</label><input name="freeabove" inputmode="decimal" placeholder="none" value="${r.free_delivery_above_paise ? r.free_delivery_above_paise / 100 : ''}"></div></div>
      <label class="row" style="font-weight:600"><input type="checkbox" name="approved" ${r.approved ? 'checked' : ''} style="width:22px;min-height:22px"> Approved</label><label class="row" style="font-weight:600"><input type="checkbox" name="visible" ${r.admin_visible ? 'checked' : ''} style="width:22px;min-height:22px"> Visible to customers</label><button class="btn block mt" type="submit">Save</button></form>`); };
  PL.forms.rest = async (f) => { const v = PL.form(f); const b = { name: v.name, cuisine: v.cuisine, address: v.address, phone: v.phone, commission_bps: Math.round(Number(v.commission) * 100), markup_paise: paise(v.markup), packing_buffer_min: +v.buffer || 0, min_order_paise: paise(v.minorder), free_delivery_above_paise: v.freeabove ? paise(v.freeabove) : null, approved: !!f.approved.checked, admin_visible: !!f.visible.checked };
    const r = await PL.run(() => (f.dataset.id ? PL.put('/api/admin/restaurants/' + f.dataset.id, b) : P('/restaurants', b)), 'Saved'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };
  PL.actions['go-close'] = (el) => { PL.closeModal(); setTimeout(() => PL.go(el.dataset.path), 150); };
  PL.actions['rest-orders'] = async (el) => { const { orders } = await A(`/restaurants/${el.dataset.id}/orders`); PL.modal(`<h3>Restaurant orders</h3>${orders.map((o) => `<div class="card row between"><div>${PL.code(o.order_code)}<div class="small mute">${PL.dt(o.created_at)} · payout ${rs(o.restaurant_payout_paise)}</div></div><div class="right">${PL.chip(o.status)}<br><button class="btn ghost sm mt2" data-act="go-close" data-path="/search/${o.order_code}">Open</button></div></div>`).join('') || '<p class="mute">No orders yet.</p>'}`); };
  PL.actions['rest-users'] = async (el) => { const { users } = await A(`/restaurants/${el.dataset.id}/users`); PL.modal(`<h3>Restaurant logins</h3>${users.map((u) => `<div class="card row"><div class="grow"><b>${e(u.name)}</b><div class="small mute">${e(u.phone)}</div></div>${u.active ? '<span class="chip ok">Active</span>' : '<span class="chip bad">Off</span>'}<button class="btn ${u.active ? 'danger' : ''} sm" data-act="user-active" data-id="${u.id}" data-v="${u.active ? 0 : 1}">${u.active ? 'Deactivate' : 'Activate'}</button></div>`).join('') || '<p class="mute">No logins yet.</p>'}`); };
  PL.actions['rest-owner'] = (el) => PL.modal(`<h3>Create restaurant login</h3><form data-form="user" data-role="restaurant" data-rid="${el.dataset.id}"><label>Owner name</label><input name="name" required><label>Mobile (login ID)</label><input name="phone" placeholder="+919876543210" required><label>Password (10+ characters)</label><input name="password" type="text" minlength="10" required autocomplete="off"><button class="btn block mt" type="submit">Create login</button></form>`);
  PL.actions['rest-menu'] = async (el) => { const { items } = await A(`/restaurants/${el.dataset.id}/menu`); PL.modal(`<h3>Menu</h3>${items.map((i) => `<div class="kv"><span>${e(i.name)}${i.available ? '' : ' <span class="chip bad">Sold out</span>'}</span><span>${rs(i.base_price_paise)} · ${i.prep_time_min}m</span></div>`).join('') || '<p class="mute">No items.</p>'}`); };
  PL.forms.user = async (f) => { const v = PL.form(f), role = f.dataset.role; const b = { role, name: v.name, phone: v.phone.replace(/\s/g, ''), password: v.password }; if (role === 'restaurant') b.restaurant_id = Number(f.dataset.rid); 
    const r = await PL.run(() => P('/users', b), `${role === 'rider' ? 'Rider' : 'Login'} created. Share the credentials securely`); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };

  // ---------- locations ----------
  async function locations() { const { locations } = await A('/locations');
    return `<div class="row between"><h2>Delivery locations</h2><button class="btn sm" data-act="loc-edit">${PL.icon('plus', 'width="18" height="18"')} Add</button></div><div class="mt2">${tbl(['Name', 'Type', 'Fee', 'Distance', 'Status', ''], locations.map((l) => [`<b>${e(l.name)}</b><div class="small mute">${e(l.address)}</div>`, e(l.kind || ''), rs(l.delivery_fee_paise), l.distance_km ? l.distance_km + ' km' : '', l.active ? PL.chip('approved').replace('Approved', 'Active') : '<span class="chip">Inactive</span>', `<button class="btn ghost sm" data-act="loc-edit" data-id="${l.id}">Edit</button>`]))}</div>`; }
  PL.actions['loc-edit'] = async (el) => { const l = el.dataset.id ? (await A('/locations')).locations.find((x) => x.id == el.dataset.id) : { delivery_fee_paise: 4000, active: 1 };
    PL.modal(`<h3>${l.id ? 'Edit' : 'Add'} location</h3><form data-form="loc" data-id="${l.id || ''}"><label>Name</label><input name="name" value="${e(l.name || '')}" required><label>Type</label><select name="kind">${['Hostel', 'PG', 'Apartment', 'College', 'Building', 'Landmark', 'Other'].map((k) => `<option ${l.kind === k ? 'selected' : ''}>${k}</option>`).join('')}</select><label>Full address</label><input name="address" value="${e(l.address || '')}" required><label>Area</label><input name="area" value="${e(l.area || '')}"><label>Contact</label><input name="contact" value="${e(l.contact || '')}">
      <div class="grid g2"><div><label>Delivery fee (₹)</label><input name="fee" inputmode="decimal" value="${l.delivery_fee_paise / 100}" required></div><div><label>Distance (km)</label><input name="km" inputmode="decimal" value="${l.distance_km ?? ''}"></div></div><label>Google Maps link</label><input name="maps" type="url" value="${e(l.maps_link || '')}"><div class="grid g2"><div><label>Latitude</label><input name="lat" inputmode="decimal" value="${l.lat ?? ''}"></div><div><label>Longitude</label><input name="lng" inputmode="decimal" value="${l.lng ?? ''}"></div></div>
      <label class="row" style="font-weight:600"><input type="checkbox" name="active" ${l.active ? 'checked' : ''} style="width:22px;min-height:22px"> Active</label><button class="btn block mt" type="submit">Save</button></form>`); };
  PL.forms.loc = async (f) => { const v = PL.form(f), n = (x) => (x === '' || x == null ? null : Number(x)); const b = { name: v.name, kind: v.kind, address: v.address, area: v.area, contact: v.contact, delivery_fee_paise: paise(v.fee), distance_km: n(v.km), maps_link: v.maps, lat: n(v.lat), lng: n(v.lng), active: !!f.active.checked };
    const r = await PL.run(() => (f.dataset.id ? PL.put('/api/admin/locations/' + f.dataset.id, b) : P('/locations', b)), 'Saved'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };

  // ---------- delivery-agent verification queue ----------
  const RQ = [['pending', 'Pending verification'], ['corrections_requested', 'Corrections requested'], ['reverification_required', 'Re-verification'], ['draft', 'Not submitted'], ['approved', 'Approved'], ['rejected', 'Rejected'], ['suspended', 'Suspended'], ['all', 'All']];
  S.rq = S.rq || 'pending';
  async function riders() { const { riders, counts } = await A('/riders?status=' + S.rq);
    return `<div class="row between wrap"><h2>Delivery-agent verification</h2><button class="btn sm" data-act="rider-new">${PL.icon('plus', 'width="18" height="18"')} Create agent account</button></div>
      <p class="small mute mt2">Agents can’t sign themselves up. Create the account and share the login; the agent fills in the application, and you approve it here. Only approved agents can go online or receive orders.</p>
      <div class="tabs mt2">${RQ.map(([k, l]) => `<button class="${S.rq === k ? 'on' : ''}" data-act="rq-tab" data-k="${k}">${l}${k !== 'all' && counts[k] ? ` (${counts[k]})` : ''}</button>`).join('')}</div>
      ${riders.length ? tbl(['Agent', 'Vehicle', 'Status', 'Submitted', ''], riders.map((r) => [`<b>${e(r.legal_name || r.name)}</b><div class="small mute">${e(r.phone)}${r.active ? '' : ' · <span style="color:var(--bad)">login disabled</span>'}</div>`,
        `${e(r.vehicle_category || '—')}<div class="small mute">${e(r.vehicle_reg_no || '')}</div>`, `${PL.chip(r.verification_status)}${r.missing_count && r.verification_status !== 'approved' ? `<div class="small mute">${r.missing_count} item${r.missing_count > 1 ? 's' : ''} missing</div>` : ''}`,
        r.submitted_at ? PL.dt(r.submitted_at) : '<span class="mute">—</span>', `<button class="btn sm" data-act="go" data-path="/riders/${r.id}">${r.verification_status === 'pending' ? 'Review' : 'Open'}</button>`])) : `<div class="empty">No agents in “${e(RQ.find(([k]) => k === S.rq)[1])}”.</div>`}`; }
  PL.actions['rq-tab'] = (el) => { S.rq = el.dataset.k; PL.rerender(); };
  PL.actions['rider-new'] = () => PL.modal(`<h3>Create delivery-agent account</h3><form data-form="user" data-role="rider"><label>Name</label><input name="name" required><label>Mobile (login ID)</label><input name="phone" placeholder="+919876543210" required><label>Temporary password (10+ characters)</label><input name="password" minlength="10" required autocomplete="off"><p class="small mute">The agent then completes the application in the delivery-partner app. There is no way to approve without it.</p><button class="btn block mt" type="submit">Create account</button></form>`);
  const FIELD_LABELS = { legal_name: 'Full legal name', date_of_birth: 'Date of birth', address: 'Address', emergency_phone: 'Emergency contact', photo: 'Profile photo', id_type: 'Identity document type', id_last4: 'ID last 4', id_front: 'ID front', id_back: 'ID back', vehicle_category: 'Vehicle type', vehicle_model: 'Make and model', vehicle_reg_no: 'Registration number', rc: 'RC document', vehicle_photo: 'Vehicle photo', licence_no: 'Licence number', licence_expiry: 'Licence expiry', licence: 'Licence document', insurance: 'Insurance', payout: 'Payout details' };
  async function riderDetail({ id }) { const { application: a, doc_labels: DL, id_types: IT } = await A('/riders/' + id);
    const row = (k, v) => `<dt>${k}</dt><dd>${v || '<span class="mute">—</span>'}</dd>`;
    const can = { approve: ['pending', 'suspended'].includes(a.status) && !a.missing.length && !a.problems.length, corrections: ['pending', 'approved', 'suspended', 'reverification_required'].includes(a.status), reject: ['pending', 'corrections_requested', 'reverification_required', 'draft'].includes(a.status), suspend: ['approved', 'reverification_required'].includes(a.status) };
    return `<div class="card status-card st-${a.status}"><div class="row between wrap"><div><div class="small mute">Delivery agent #${a.user.id}</div><h2>${e(a.legal_name || a.user.name)}</h2><div class="small mute">${e(a.user.phone)} ${a.phone_verified ? '<span class="chip ok">mobile verified</span>' : '<span class="chip warn">mobile not verified</span>'}</div></div>${PL.chip(a.status)}</div>
      ${a.active_deliveries.length ? `<div class="banner info mt2" style="margin-bottom:0">Has ${a.active_deliveries.length} delivery in progress (${a.active_deliveries.map((x) => e(x.order_code)).join(', ')}). It can be finished whatever you decide here.</div>` : ''}
      ${a.missing.length ? `<div class="banner warn mt2" style="margin-bottom:0"><b>Missing:</b> ${a.missing.map((m) => e(m.label)).join(', ')}</div>` : ''}${a.problems.length ? `<div class="banner bad mt2" style="margin-bottom:0">${a.problems.map(e).join(' ')}</div>` : ''}
      <div class="row wrap mt">${can.approve ? `<button class="btn" data-act="rv" data-id="${id}" data-a="approve">Approve</button>` : ''}${can.corrections ? `<button class="btn ghost" data-act="rv" data-id="${id}" data-a="corrections">Request corrections</button>` : ''}${can.reject ? `<button class="btn danger" data-act="rv" data-id="${id}" data-a="reject">Reject</button>` : ''}${can.suspend ? `<button class="btn danger" data-act="rv" data-id="${id}" data-a="suspend">Suspend</button>` : ''}</div>
      ${a.status === 'pending' && !can.approve ? '<p class="small mute mt2">Approve is available once every required item is present.</p>' : ''}</div>
      <div class="grid g2-lg"><div class="card"><h3>Personal</h3><dl class="summary">${row('Legal name', e(a.legal_name))}${row('Account name', e(a.user.name))}${row('Date of birth', e(a.date_of_birth))}${row('Address', e(a.address))}${row('Emergency contact', e(a.emergency_phone))}${row('Email', e(a.email))}</dl>
        <h3 class="mt">Identity</h3><dl class="summary">${row('Document', a.id_type ? e(IT[a.id_type]) : '')}${row('Last 4', e(a.id_last4))}</dl></div>
        <div class="card"><h3>Vehicle</h3><dl class="summary">${row('Type', e(a.vehicle_category))}${row('Make / model', e([a.vehicle_make, a.vehicle_model].filter(Boolean).join(' ')))}${row('Registration', e(a.vehicle_reg_no))}${row('Licence', e(a.licence_no))}${row('Licence valid until', e(a.licence_expiry))}${row('Insurance', e(a.insurance_no))}</dl>
        <h3 class="mt">Payout</h3><dl class="summary">${row('Method', a.payout_method === 'upi' ? 'UPI' : a.payout_method === 'bank' ? 'Bank account' : '')}${a.payout_method === 'upi' ? row('UPI ID', e(a.payout_upi_hint)) : row('Account', a.bank_account_last4 ? `${e(a.bank_holder)} · ending ${e(a.bank_account_last4)} · ${e(a.bank_ifsc)}` : '')}</dl>
        ${a.payout_method ? `<button class="btn ghost sm" data-act="rv-payout" data-id="${id}">Show full payout details</button><div id="payout-full"></div>` : ''}</div></div>
      <div class="card"><h3>Documents</h3><p class="small mute">Private. Every view of an identity document is recorded in the audit log.</p><div class="docs-grid">${Object.entries(DL).map(([k, l]) => `<div class="doc"><div class="grow"><b class="small">${e(l)}</b><div class="small ${a.docs[k] ? 'ok-t' : 'mute'}">${a.docs[k] ? 'Uploaded' : 'Not uploaded'}</div></div>${a.docs[k] ? `<button class="btn ghost sm" data-act="rv-doc" data-id="${id}" data-k="${k}">Open</button>` : ''}</div>`).join('')}</div></div>
      <div class="card"><h3>Decision history</h3><p class="small mute">Permanent record; entries cannot be edited or deleted.</p>${a.history.map((h) => `<div class="hist"><div class="row between wrap">${PL.chip(h.status)}<span class="small mute">${PL.dt(h.created_at)}${h.admin_name ? ' · ' + e(h.admin_name) : h.action === 'submitted' ? ' · agent' : ' · system'}</span></div>${h.note ? `<div class="small mt2">${e(h.note)}</div>` : ''}${h.fields ? `<div class="small mute">Fields: ${h.fields.map((f) => e(FIELD_LABELS[f] || f)).join(', ')}</div>` : ''}</div>`).join('') || '<p class="mute">No decisions yet.</p>'}</div>`; }
  PL.actions['rv-doc'] = (el) => PL.openDoc(`/api/files/rider-doc/${el.dataset.id}/${el.dataset.k}`);
  PL.actions['rv-payout'] = async (el) => { const r = await PL.reauth('Show full payout details', (a) => P(`/riders/${el.dataset.id}/payout-details`, a)); if (!r) return; const p = r.payout, box = PL.$('#payout-full');
    if (box) box.innerHTML = `<div class="banner info mt2" style="margin-bottom:0">${p.method === 'upi' ? `UPI ID: <b>${e(p.upi)}</b>` : `${e(p.bank_holder)}<br>Account: <b>${e(p.bank_account)}</b><br>IFSC: <b>${e(p.bank_ifsc)}</b>`}<div class="small mute">This view was recorded in the audit log.</div></div>`; };
  PL.actions.rv = (el) => { const a = el.dataset.a, id = el.dataset.id, T = { approve: 'Approve this agent', corrections: 'Request corrections', reject: 'Reject application', suspend: 'Suspend agent' }[a];
    PL.modal(`<h3>${T}</h3><form data-form="rv" data-id="${id}" data-a="${a}">${a === 'corrections' ? `<label>What needs correcting?</label><div class="fieldpick">${Object.entries(FIELD_LABELS).map(([k, l]) => `<label class="check"><input type="checkbox" name="f_${k}"> ${l}</label>`).join('')}</div>` : ''}
      <label>${a === 'approve' ? 'Note (optional)' : 'Reason (required, shown to the agent)'}</label><textarea name="note" maxlength="500" ${a === 'approve' ? '' : 'required minlength="5"'}></textarea>
      ${a === 'approve' ? '<p class="small mute">The agent becomes eligible for new deliveries once they go online.</p>' : a === 'suspend' ? '<p class="small mute">The agent goes offline and gets no new deliveries. Deliveries already in progress can be finished.</p>' : ''}<button class="btn ${a === 'approve' ? '' : 'danger'} block mt" type="submit">Continue</button></form>`); };
  PL.forms.rv = async (f) => { const v = PL.form(f), a = f.dataset.a, id = f.dataset.id, fields = Object.keys(FIELD_LABELS).filter((k) => f['f_' + k]?.checked);
    if (a === 'corrections' && !fields.length) return PL.toast('Tick at least one item to correct.', true);
    const body = { action: a, note: v.note || undefined, fields: a === 'corrections' ? fields : undefined }; PL.closeModal();
    const r = a === 'approve' || a === 'suspend' ? await PL.reauth(a === 'approve' ? 'Confirm approval' : 'Confirm suspension', (x) => P(`/riders/${id}/verify`, { ...body, ...x })) : await PL.run(() => P(`/riders/${id}/verify`, body));
    if (r) { PL.toast('Decision recorded'); setTimeout(PL.rerender, 80); } };
  PL.actions['user-active'] = async (el) => { if (!(await PL.confirm(el.dataset.v === '1' ? 'Reactivate this account?' : 'Deactivate this account? They will be signed out.', 'Confirm'))) return; const r = await PL.run(() => P(`/users/${el.dataset.id}/active`, { active: el.dataset.v === '1' }), 'Updated'); if (r) { if (document.querySelector('.ov')) PL.closeModal(); setTimeout(PL.rerender, 100); } };

  // ---------- cashouts ----------
  async function cashouts() { const { cashouts } = await A('/cashouts');
    return `<h2>Cashout requests</h2><div class="mt2">${tbl(['Request', 'Account', 'Amount', 'Available', 'Method', 'Status', ''], cashouts.map((c) => [`#${c.id}<div class="small mute">${PL.dt(c.created_at)}</div><button class="copy" style="margin:4px 0 0" data-act="co-records" data-id="${c.id}">Records</button>`, `<b>${e(c.account_name || '')}</b><div class="small mute">${c.account_type}</div>`, rs(c.amount_paise), rs(c.available_paise), `${c.payout_method.toUpperCase()}<div class="small mute">${e(c.beneficiary)}</div>`, PL.chip(c.status) + (c.reject_reason ? `<div class="small mute">${e(c.reject_reason)}</div>` : '') + (c.txn_reference ? `<div class="small code">${e(c.txn_reference)}</div>` : ''),
      c.status === 'PENDING' || c.status === 'APPROVED' ? `<div class="row wrap">${c.status === 'PENDING' ? `<button class="btn ghost sm" data-act="co" data-id="${c.id}" data-a="approve">Approve</button>` : ''}<button class="btn sm" data-act="co" data-id="${c.id}" data-a="pay" data-amt="${c.amount_paise}">Mark paid</button><button class="btn danger sm" data-act="co" data-id="${c.id}" data-a="reject">Reject</button></div>` : c.status === 'PAID' ? `<button class="btn ghost sm" data-act="view-proof" data-id="${c.id}">Proof</button>` : '']))}</div>`; }
  PL.actions['co-records'] = async (el) => { const d = await A(`/cashouts/${el.dataset.id}/records`); PL.modal(`<h3>Linked records</h3><p class="small mute">Latest ledger entries for this account. Balance now: ${rs(d.balance.available)} available, ${rs(d.balance.pending)} reserved.</p>${d.records.map((x) => `<div class="kv"><span>${x.order_code ? PL.code(x.order_code) : '<span class="mute">Payout</span>'}<div class="small mute">${e(x.kind.replace(/_/g, ' '))} · ${PL.dt(x.created_at)}</div></span><b style="color:${x.amount_paise < 0 ? 'var(--bad)' : 'var(--ok)'}">${rs(x.amount_paise)}</b></div>`).join('') || '<p class="mute">No entries.</p>'}`); };
  PL.actions.co = async (el) => { const { id, a } = el.dataset;
    if (a === 'approve') { const r = await PL.run(() => P(`/cashouts/${id}/approve`), 'Approved'); if (r) PL.rerender(); return; }
    if (a === 'reject') return PL.modal(`<h3>Reject request #${id}</h3><form data-form="co-reject" data-id="${id}"><label>Reason</label><input name="reason" required maxlength="200"><button class="btn danger block mt" type="submit">Reject</button></form>`);
    PL.modal(`<h3>Mark #${id} as paid</h3><p class="small mute">Pay ${rs(Number(el.dataset.amt))} manually, then record it here. The account sees the proof you upload.</p><form data-form="co-pay" data-id="${id}"><label>Transaction reference (UTR)</label><input name="ref" required minlength="4"><label>Payment screenshot</label><input type="file" name="proof" accept="image/*,application/pdf" required><button class="btn block mt" type="submit">Confirm payout</button></form>`); };
  PL.forms['co-reject'] = async (f) => { const r = await PL.run(() => P(`/cashouts/${f.dataset.id}/reject`, { reason: PL.form(f).reason }), 'Rejected'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };
  PL.forms['co-pay'] = async (f) => { let proof; try { proof = await PL.readFile(f.proof.files[0]); } catch (x) { return PL.toast(x.message, true); } const r = await PL.run(() => P(`/cashouts/${f.dataset.id}/pay`, { txn_reference: PL.form(f).ref, proof }), 'Payout recorded'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };

  // ---------- surge ----------
  async function surge() { const [d, l] = await Promise.all([A('/surge'), A('/locations')]); S.locs = l.locations;
    return `<div class="row between"><h2>Surge charges</h2><button class="btn sm" data-act="rule-edit">${PL.icon('plus', 'width="18" height="18"')} New rule</button></div><div class="stats mt2">${stat(rs(d.collected_paise), 'Surge collected (delivered)')}${stat(d.rules.filter((r) => r.active).length, 'Active rules')}</div>
      <div class="sec">Rules</div>${d.rules.map((r) => `<div class="card row"><div class="grow"><b>${e(r.name)}</b><div class="small mute">${r.kind === 'fixed' ? rs(r.value) : r.value / 100 + '%'} ${r.location_id ? '· ' + e(S.locs.find((x) => x.id === r.location_id)?.name || 'location') : '· all areas'} ${r.starts_at ? '· from ' + PL.dt(r.starts_at) : ''} ${r.ends_at ? 'to ' + PL.dt(r.ends_at) : ''}</div></div>${r.active ? PL.chip('approved').replace('Approved', 'Active') : '<span class="chip">Off</span>'}<button class="btn ghost sm" data-act="rule-edit" data-id="${r.id}">Edit</button></div>`).join('') || '<div class="empty">No rules.</div>'}
      <div class="sec">Restaurant requests</div>${d.requests.map((q) => `<div class="card"><div class="row between"><b>${e(q.restaurant)}</b>${PL.chip(q.status)}</div><div class="small">${e(q.reason)} ${q.requested_paise ? '· suggests ' + rs(q.requested_paise) : ''}</div>${q.status === 'PENDING' ? `<div class="row mt2"><button class="btn sm" data-act="req" data-id="${q.id}" data-ok="1">Approve</button><button class="btn danger sm" data-act="req" data-id="${q.id}" data-ok="0">Reject</button></div>` : ''}</div>`).join('') || '<div class="empty">No requests.</div>'}
      <div class="sec">Orders that paid surge</div>${d.orders.map((o) => `<div class="kv"><span>${PL.code(o.order_code)}</span><b>${rs(o.surge_paise)}</b></div>`).join('') || '<div class="empty">None yet.</div>'}`; }
  PL.actions['rule-edit'] = async (el) => { const d = await A('/surge'); const r = el.dataset.id ? d.rules.find((x) => x.id == el.dataset.id) : { kind: 'fixed', value: 1000, active: 0 };
    PL.modal(`<h3>${r.id ? 'Edit' : 'New'} surge rule</h3><form data-form="rule" data-id="${r.id || ''}"><label>Name</label><input name="name" value="${e(r.name || '')}" required><div class="grid g2"><div><label>Type</label><select name="kind"><option value="fixed" ${r.kind === 'fixed' ? 'selected' : ''}>Fixed ₹</option><option value="percent" ${r.kind === 'percent' ? 'selected' : ''}>Percent of items</option></select></div><div><label>Amount (₹ or %)</label><input name="value" inputmode="decimal" value="${r.kind === 'fixed' ? r.value / 100 : r.value / 100}" required></div></div>
      <label>Area</label><select name="loc"><option value="">All delivery areas</option>${(S.locs || []).map((l) => `<option value="${l.id}" ${r.location_id === l.id ? 'selected' : ''}>${e(l.name)}</option>`).join('')}</select><div class="grid g2"><div><label>Starts (optional)</label><input type="datetime-local" name="from" value="${r.starts_at ? new Date(r.starts_at).toLocaleString('sv').slice(0, 16).replace(' ', 'T') : ''}"></div><div><label>Ends (optional)</label><input type="datetime-local" name="to" value="${r.ends_at ? new Date(r.ends_at).toLocaleString('sv').slice(0, 16).replace(' ', 'T') : ''}"></div></div>
      <label class="row" style="font-weight:600"><input type="checkbox" name="active" ${r.active ? 'checked' : ''} style="width:22px;min-height:22px"> Active (customers see it before paying)</label><button class="btn block mt" type="submit">Save</button></form>`); };
  PL.forms.rule = async (f) => { const v = PL.form(f); const b = { name: v.name, kind: v.kind, value: Math.round(Number(v.value) * 100), location_id: v.loc ? Number(v.loc) : null, starts_at: v.from ? new Date(v.from).toISOString() : null, ends_at: v.to ? new Date(v.to).toISOString() : null, active: !!f.active.checked };
    const r = await PL.run(() => (f.dataset.id ? PL.put('/api/admin/surge/rules/' + f.dataset.id, b) : P('/surge/rules', b)), 'Saved'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };
  PL.actions.req = async (el) => { const r = await PL.run(() => P(`/surge/requests/${el.dataset.id}/decide`, { approve: el.dataset.ok === '1' }), el.dataset.ok === '1' ? 'Approved. Create or activate a rule to apply it' : 'Rejected'); if (r) PL.rerender(); };


  // ---------- operating expenses ----------
  async function expenses() { const { expenses } = await A('/expenses'); const today = new Date(Date.now() + 330 * 60_000).toISOString().slice(0, 10);
    return `<h2>Operating expenses</h2><p class="small mute mt2">Marketing, rent, salaries, SMS or hosting costs. They are subtracted from the estimated net profit on the Overview.</p>
      <form data-form="expense" class="card mt2"><div class="grid g2"><div><label>Date</label><input type="date" name="date" value="${today}" required></div><div><label>Amount (₹)</label><input name="amt" inputmode="decimal" required></div></div><label>Category</label><input name="cat" list="expcats" maxlength="40" required placeholder="Marketing"><datalist id="expcats"><option>Marketing</option><option>Hosting</option><option>Salaries</option><option>Rent</option><option>Messaging</option><option>Other</option></datalist><label>Note (optional)</label><input name="note" maxlength="200"><button class="btn block mt" type="submit">Add expense</button></form>
      ${expenses.map((x) => `<div class="card row between"><div><b>${rs(x.amount_paise)}</b> · ${e(x.category)}<div class="small mute">${e(x.spent_on)}${x.note ? ' · ' + e(x.note) : ''}</div></div><button class="btn danger sm" data-act="exp-del" data-id="${x.id}">Delete</button></div>`).join('') || '<div class="empty">No expenses recorded.</div>'}`; }
  PL.forms.expense = async (f) => { const v = PL.form(f); const r = await PL.run(() => P('/expenses', { spent_on: v.date, category: v.cat, amount_paise: paise(v.amt), note: v.note || undefined }), 'Expense added'); if (r) PL.rerender(); };
  PL.actions['exp-del'] = async (el) => { if (!(await PL.confirm('Delete this expense?', 'Delete'))) return; const r = await PL.run(() => PL.api('/api/admin/expenses/' + el.dataset.id, { method: 'DELETE' }), 'Deleted'); if (r) PL.rerender(); };

  // ---------- settings / more ----------
  const SET = [['gps_delivery_fee_paise', 'GPS delivery fee (paise)'], ['rider_payout_paise', 'Rider payout per delivery (paise)'], ['tax_bps', 'Tax (basis points)'], ['gateway_fee_bps', 'Est. gateway fee (basis points)'], ['rider_to_restaurant_min', 'Rider to restaurant (min)'], ['default_delivery_min', 'Default delivery time (min)'], ['minutes_per_km', 'Minutes per km'], ['max_active_per_rider', 'Max active orders per rider'], ['rider_online_ttl_sec', 'Rider heartbeat timeout (sec)'], ['payment_timeout_min', 'Payment timeout (min)']];
  async function settings() { const { settings: s } = await A('/settings'); const { refunds } = await A('/refunds'); const mfa = (await A('/mfa')).enabled;
    return `<h2>Settings</h2><form data-form="settings" class="card mt2"><h3>Delivery confirmation code</h3><label>Mode</label><select name="delivery_otp_mode"><option value="per_order" ${s.delivery_otp_mode === 'per_order' ? 'selected' : ''}>Unique code per order (recommended)</option><option value="fixed" ${s.delivery_otp_mode === 'fixed' ? 'selected' : ''}>Same fixed code for every order</option></select>
      <label>Fixed code (4 digits)</label><input name="fixed_delivery_otp" inputmode="numeric" maxlength="4" value="${e(s.fixed_delivery_otp)}"><div class="banner warn mt2" style="margin-bottom:0">A shared code is a security risk: anyone who learns it can complete deliveries without the customer. Use only for the pilot.</div>
      <h3 class="mt">Payout methods</h3><label>Methods restaurants and riders can choose (comma separated)</label><input name="payout_methods" value="${e(s.payout_methods)}" placeholder="upi,bank"><h3 class="mt">Business rules</h3>${SET.map(([k, l]) => `<label>${l}</label><input name="${k}" inputmode="numeric" value="${e(s[k])}">`).join('')}<button class="btn block mt" type="submit">Save settings</button></form>
      <div class="sec">Refunds</div>${refunds.map((r) => `<div class="card row between"><div>${PL.code(r.order_code)}<div class="small mute">${e(r.reason || '')}</div></div><div class="right"><b>${rs(r.amount_paise)}</b><br>${PL.chip(r.status)}</div></div>`).join('') || '<div class="empty">No refunds.</div>'}
      <div class="sec">Account security</div><div class="card row between"><div class="grow"><b>Two-factor sign-in</b><div class="small mute">${mfa ? 'On: an authenticator code is required at sign-in.' : 'Off. Add an authenticator app code for extra protection.'}</div></div><button class="btn ${mfa ? 'danger' : ''} sm" data-act="${mfa ? 'mfa-off' : 'mfa-setup'}">${mfa ? 'Turn off' : 'Set up'}</button></div>${PL.push.card('admin')}<button class="btn ghost block" data-act="go" data-path="/audit">Audit log</button><button class="btn ghost block mt2" data-act="logout">Sign out</button>`; }
  PL.actions['mfa-setup'] = async () => { const r = await PL.run(() => P('/mfa/setup')); if (!r) return;
    PL.modal(`<h3>Set up two-factor</h3><p class="small mute">In an authenticator app (Google Authenticator, Authy, 1Password…) choose “Enter a setup key” and type:</p><div class="otp" style="font-size:1.05rem;letter-spacing:.08em;word-break:break-all">${e(r.secret.match(/.{1,4}/g).join(' '))}</div><div class="small mute mt2">Account: Pakka Local · Time based · 6 digits. Or paste this link into your app: <span class="code" style="word-break:break-all">${e(r.uri)}</span></div>
      <form data-form="mfa-enable" class="mt"><label>Enter the 6-digit code it shows</label><input name="code" inputmode="numeric" maxlength="6" required autocomplete="off"><button class="btn block mt" type="submit">Turn on two-factor</button></form>`); };
  PL.forms['mfa-enable'] = async (f) => { const r = await PL.run(() => P('/mfa/enable', { code: PL.form(f).code }), 'Two-factor is on'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };
  PL.actions['mfa-off'] = () => PL.modal(`<h3>Turn off two-factor</h3><form data-form="mfa-disable"><label>Enter a current code (not the one you just used to sign in)</label><input name="code" inputmode="numeric" maxlength="6" required autocomplete="off"><button class="btn danger block mt" type="submit">Turn off</button></form>`);
  PL.forms['mfa-disable'] = async (f) => { const r = await PL.run(() => P('/mfa/disable', { code: PL.form(f).code }), 'Two-factor is off'); if (r) { PL.closeModal(); setTimeout(PL.rerender, 80); } };
  PL.forms.settings = async (f) => { const r = await PL.run(() => PL.put('/api/admin/settings', { settings: PL.form(f) }), 'Settings saved'); if (r) PL.rerender(); };
  async function audit() { const { logs } = await A('/audit'); return `<h2>Audit log</h2><div class="mt2">${tbl(['When', 'Who', 'Action', 'Target'], logs.map((l) => [PL.dt(l.created_at), e(l.actor || l.actor_role || ''), e(l.action), e((l.target_type || '') + ' ' + (l.target_id ?? ''))]))}</div>`; }

  // ---------- broadcasts (Web Push only) ----------
  const AUD = { all_customers: 'All customers', location: 'Customers who ordered to a location', ordered_recent: 'Customers who ordered in the last N days', inactive: 'Inactive customers (no order in N days)', riders: 'Riders only', restaurants: 'Restaurants only', user: 'A specific user (phone)' };
  const audName = (c) => AUD[c.audience_type] + (c.audience_param ? ` (${c.audience_param})` : '');
  async function broadcast() { const [{ campaigns }, { locations }, { restaurants: rl }] = await Promise.all([A('/campaigns'), A('/locations'), A('/restaurants')]);
    return `<h2>Notifications</h2><p class="small mute mt2">Promotions go by push notification only, to people who haven’t opted out. Order updates are never affected.</p>
      <form data-form="bc" class="card mt2"><label>Title</label><input name="title" maxlength="60" required><label>Message</label><textarea name="body" maxlength="200" required></textarea><label>Image (optional)</label><input type="file" name="image" accept="image/*">
      <label>Opens when tapped</label><select name="deep" id="deepsel"><option value="/user/">Customer home</option><option value="rest">A specific restaurant</option><option value="">Nothing special</option></select><div id="deeprest" class="hide"><select name="deeprest">${rl.map((r) => `<option value="${r.id}">${e(r.name)}</option>`).join('')}</select></div>
      <label>Audience</label><select name="aud" id="audsel">${Object.entries(AUD).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select>
      <div id="audp-location" class="hide"><label>Location</label><select name="p_location">${locations.map((l) => `<option value="${l.id}">${e(l.name)}</option>`).join('')}</select></div><div id="audp-days" class="hide"><label>Number of days</label><input name="p_days" type="number" min="1" max="365" value="7"></div><div id="audp-user" class="hide"><label>Phone number</label><input name="p_user" placeholder="+919876543210"></div>
      <label>When</label><select name="when" id="whensel"><option value="now">Send now</option><option value="later">Schedule for later</option></select><div id="whenp" class="hide"><input type="datetime-local" name="at"></div>
      <button class="btn block mt" type="submit" value="send">Preview audience</button><button class="btn ghost block mt2" type="submit" value="draft">Save as draft</button></form>
      <div class="sec">Campaign history</div>${campaigns.map((c) => `<div class="card"><div class="row between"><b>${e(c.title)}</b>${PL.chip(c.status === 'completed' ? 'approved' : c.status === 'cancelled' ? 'rejected' : 'pending').replace(/>[^<]+</, '>' + c.status + '<')}</div><div class="small">${e(c.body)}</div><div class="small mute">${e(audName(c))} · ${c.status === 'scheduled' ? 'Scheduled ' : ''}${c.scheduled_at ? PL.dt(c.scheduled_at) : 'Not sent yet'}</div>
        <div class="stats mt2">${stat(c.targeted, 'Targeted')}${stat(c.stats.sent, 'Sent')}${stat(c.stats.failed, 'Failed')}${stat(c.stats.clicked, 'Clicked')}</div>${c.capped ? `<div class="small mute mt2">${c.capped} skipped by the daily limit</div>` : ''}${c.status === 'scheduled' ? `<button class="btn danger sm mt2" data-act="bc-cancel" data-id="${c.id}">Cancel scheduled send</button>` : ''}${c.status === 'draft' ? `<div class="row mt2"><button class="btn sm grow" data-act="bc-send" data-id="${c.id}">Send now</button><button class="btn danger sm grow" data-act="bc-del" data-id="${c.id}">Delete draft</button></div>` : ''}</div>`).join('') || '<div class="empty">No campaigns yet.</div>'}`; }
  const audParam = (v) => ({ location: v.p_location, ordered_recent: v.p_days, inactive: v.p_days, user: (v.p_user || '').replace(/\s/g, '') }[v.aud] ?? null);
  document.addEventListener('change', (ev) => { if (ev.target.id === 'audsel') { const a = ev.target.value; PL.$('#audp-location').classList.toggle('hide', a !== 'location'); PL.$('#audp-days').classList.toggle('hide', !['ordered_recent', 'inactive'].includes(a)); PL.$('#audp-user').classList.toggle('hide', a !== 'user'); }
    if (ev.target.id === 'deepsel') PL.$('#deeprest').classList.toggle('hide', ev.target.value !== 'rest');
    if (ev.target.id === 'whensel') PL.$('#whenp').classList.toggle('hide', ev.target.value !== 'later'); });
  PL.forms.bc = async (f, ev) => { const v = PL.form(f); const deep = v.deep === 'rest' ? `/user/#/r/${v.deeprest}` : v.deep || null;
    if (ev?.submitter?.value === 'draft') { let image; try { if (f.image.files[0]) image = await PL.readFile(f.image.files[0]); } catch (x) { return PL.toast(x.message, true); }
      const r = await PL.run(() => P('/campaigns', { title: v.title, body: v.body, deep_link: deep, image, audience_type: v.aud, audience_param: audParam(v), draft: true }), 'Draft saved'); if (r) PL.rerender(); return; } const prev = await PL.run(() => P('/campaigns/preview', { audience_type: v.aud, audience_param: audParam(v) })); if (!prev) return;
    if (v.when === 'later' && !v.at) return PL.toast('Choose a date and time.', true);
    if (!(await PL.confirm(`Send “${v.title}” to ${prev.audience_size} ${prev.audience_size === 1 ? 'person' : 'people'}${v.when === 'later' ? ' at ' + PL.dt(new Date(v.at).toISOString()) : ' now'}?`, 'Send'))) return;
    let image; try { if (f.image.files[0]) image = await PL.readFile(f.image.files[0]); } catch (x) { return PL.toast(x.message, true); }
    const r = await PL.run(() => P('/campaigns', { title: v.title, body: v.body, deep_link: deep, image, audience_type: v.aud, audience_param: audParam(v), scheduled_at: v.when === 'later' ? new Date(v.at).toISOString() : undefined }), v.when === 'later' ? 'Scheduled' : 'Sending'); if (r) PL.rerender(); };
  PL.actions['bc-send'] = async (el) => { if (!(await PL.confirm('Send this draft now?', 'Send'))) return; const r = await PL.run(() => P(`/campaigns/${el.dataset.id}/send`, {}), 'Sending'); if (r) PL.rerender(); };
  PL.actions['bc-del'] = async (el) => { if (!(await PL.confirm('Delete this draft?', 'Delete'))) return; const r = await PL.run(() => PL.api('/api/admin/campaigns/' + el.dataset.id, { method: 'DELETE' }), 'Deleted'); if (r) PL.rerender(); };
  PL.actions['bc-cancel'] = async (el) => { if (!(await PL.confirm('Cancel this scheduled campaign?', 'Cancel campaign'))) return; const r = await PL.run(() => P(`/campaigns/${el.dataset.id}/cancel`), 'Cancelled'); if (r) PL.rerender(); };
  async function more() { const mk = (p, ic, t, d) => `<button class="card row" style="width:100%;text-align:left;cursor:pointer" data-act="go" data-path="${p}"><span style="color:var(--brand)">${PL.icon(ic)}</span><div class="grow"><b>${t}</b><div class="small mute">${d}</div></div></button>`;
    return mk('/restaurants', 'shop', 'Restaurants', 'Add, hide, commission and markup') + mk('/locations', 'pin', 'Delivery locations', 'Hostels, PGs, apartments') + mk('/riders', 'bike', 'Delivery-agent verification', 'Review applications, approve, request corrections') + mk('/broadcast', 'bell', 'Notifications', 'Send promotions and announcements') + mk('/map', 'pin', 'Live deliveries', 'Where each active rider is right now') + mk('/expenses', 'wallet', 'Operating expenses', 'Feeds the net-profit estimate') + mk('/surge', 'bolt', 'Surge charges', 'Rules and restaurant requests') + mk('/settings', 'gear', 'Settings and refunds', 'Payout, tax and OTP rules'); }

  PL.start({ portal: 'admin', name: 'Admin', home: '/overview', loginView: (root) => PL.staffLogin(root, { title: 'Super Admin', blurb: 'Pakka Local control centre.' }),
    right: () => `<button class="iconbtn" data-act="logout" aria-label="Sign out">${PL.icon('x')}</button>`,
    tabs: [{ path: '/overview', label: 'Overview', icon: 'chart' }, { path: '/orders', label: 'Orders', icon: 'orders' }, { path: '/search', label: 'Order ID', icon: 'search' }, { path: '/cashouts', label: 'Cashouts', icon: 'wallet' }, { path: '/more', label: 'More', icon: 'menu' }],
    onReady: () => { const t = async () => { try { const o = await A('/overview?preset=today'); PL.badge('/cashouts', o.pending_cashouts); } catch {} }; t(); const iv = setInterval(t, 5000); PL.hooks.stop = [() => clearInterval(iv)]; },
    routes: { '/overview': { title: 'Overview', render: overview, poll: 3000 }, '/orders': { title: 'Orders', render: orders, poll: 3000 }, '/search': { title: 'Order ID search', render: search }, '/search/:code': { title: 'Order details', render: orderDetail, poll: 4000 }, '/cashouts': { title: 'Cashout requests', render: cashouts, poll: 3000 },
      '/more': { title: 'More', render: more }, '/restaurants': { title: 'Restaurants', render: restaurants, poll: 5000 }, '/locations': { title: 'Delivery locations', render: locations }, '/riders': { title: 'Agent verification', render: riders, poll: 8000 }, '/riders/:id': { title: 'Agent application', render: riderDetail }, '/surge': { title: 'Surge charges', render: surge }, '/expenses': { title: 'Expenses', render: expenses }, '/broadcast': { title: 'Notifications', render: broadcast, poll: 5000 }, '/settings': { title: 'Settings', render: settings }, '/audit': { title: 'Audit log', render: audit } } });
})();
